const request = $('Prepare Policy Verification Request').first().json;
const policy = $input.first()?.json ?? {};

const policyFound = policy.policy_found === true;
const reasons = [];

let dateCheck = "UNVERIFIED";

if (!policyFound) {
  reasons.push("POLICY_NOT_FOUND");
} else {
  if (policy.policy_status !== "ACTIVE") {
    reasons.push("POLICY_NOT_CONFIRMED_ACTIVE");
  }

  if (policy.source_verified !== true) {
    reasons.push("POLICY_SOURCE_NOT_VERIFIED");
  }

  const accidentDate = request.accident_date;
  const startDate = policy.effective_date;
  const endDate = policy.expiry_date;

  const validDate = value =>
    typeof value === "string" &&
    /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    !Number.isNaN(Date.parse(value)) &&
    new Date(value).toISOString().slice(0, 10) === value;

  if (
    !validDate(accidentDate) ||
    !validDate(startDate) ||
    !validDate(endDate)
  ) {
    dateCheck = "UNVERIFIED";
    reasons.push("INVALID_OR_MISSING_DATES");
  } else if (
    accidentDate >= startDate &&
    accidentDate <= endDate
  ) {
    dateCheck = "WITHIN_POLICY_PERIOD";
  } else {
    dateCheck = "OUTSIDE_POLICY_PERIOD";
    reasons.push("ACCIDENT_OUTSIDE_POLICY_PERIOD");
  }
}

return [{
  json: {
    claim_id: request.claim_id,
    claim_version: request.claim_version,
    job_id: request.job_id,
    correlation_id: request.correlation_id,
    policy_number: request.policy_number,

    accident_date: request.accident_date ?? null,
    effective_date: policyFound ? policy.effective_date : null,
    expiry_date: policyFound ? policy.expiry_date : null,

    policy_found: policyFound,
    policy_status: policyFound
      ? policy.policy_status
      : "MISSING",
    source_verified:
      policyFound && policy.source_verified === true,

    date_check: dateCheck,
    verification_status: "UNVERIFIED",
    coverage_status: "UNVERIFIED",
    evidence_status: "UNVERIFIED",

    requires_human_review: reasons.length > 0,
    review_reasons: reasons,
    claim_status_changed: false
  }
}];

