const input = $input.first().json;
const verification = input.policy_verification ?? {};

const findings = [];
const missingInformation = [];

function addFinding(code, severity, message) {
  findings.push({ code, severity, message });
}

function addMissing(value) {
  if (!missingInformation.includes(value)) {
    missingInformation.push(value);
  }
}

// 1. Policy existence
if (verification.policy_found !== true) {
  addFinding(
    "POLICY_NOT_FOUND",
    "HIGH",
    "Policy record was not found."
  );
}

// 2. Policy source verification
if (verification.source_verified !== true) {
  addFinding(
    "UNVERIFIED_POLICY_SOURCE",
    "HIGH",
    "Policy source has not been verified."
  );
  addMissing("Verified policy source");
}

// 3. Policy status
if (verification.policy_status !== "ACTIVE") {
  addFinding(
    "POLICY_STATUS_REQUIRES_REVIEW",
    "MEDIUM",
    "Policy status is not confirmed as ACTIVE."
  );
}

// 4. Accident date
if (verification.date_check === "OUTSIDE_POLICY_PERIOD") {
  addFinding(
    "DATE_OUTSIDE_POLICY_PERIOD",
    "HIGH",
    "Accident date is outside the recorded policy period."
  );
}

if (verification.date_check !== "WITHIN_POLICY_PERIOD") {
  addMissing("Verified policy coverage dates");
}

// 5. Coverage verification
if (verification.coverage_status !== "VERIFIED") {
  addMissing("Confirmed coverage terms");
}

// 6. Supporting evidence
if (verification.evidence_status !== "VERIFIED") {
  addMissing("Verified supporting evidence");
}

// 7. Incident description
if (
  typeof input.incident_description !== "string" ||
  !input.incident_description.trim()
) {
  addMissing("Incident description");
}

// 8. Human review policy
// MVP: all preliminary analyses require supervisor review.
const requiresHumanReview = true;

const summary = findings.length > 0 || missingInformation.length > 0
  ? "Preliminary checks identified issues requiring verification."
  : "Preliminary checks completed. Supervisor review is still required.";

return [{
  json: {
    schema_version: "1.0",

    job_id: input.job_id,
    claim_id: input.claim_id,
    claim_version: input.claim_version,

    claim_context: {
      claim_type: input.claim_type,
      policy_number: input.policy_number,
      accident_date: input.accident_date,
      incident_description: input.incident_description
    },

    policy_verification: verification,

    analysis_type: "RULE_BASED_PRELIMINARY",
    analysis_status: "COMPLETED",

    summary,
    findings,
    missing_information: missingInformation,

    recommendation: "REFER_TO_HUMAN_REVIEW",
    requires_human_review: requiresHumanReview,

    final_claim_decision: null,
    claim_status_changed: false,

    analyzed_at: new Date().toISOString()
  }
}];

