const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const claim = data.claim_data || {};

  const requiredEnvelope = [
    "schema_version",
    "event_id",
    "event_type",
    "job_id",
    "claim_id",
    "claim_version",
    "correlation_id",
    "occurred_at"
  ];

  const requiredClaim = [
    "claim_number",
    "policy_number",
    "claim_type",
    "accident_date",
    "vehicle_plate",
    "incident_description"
  ];

  const missing = [];

  for (const field of requiredEnvelope) {
    if (
      data[field] === undefined ||
      data[field] === null ||
      data[field] === ""
    ) {
      missing.push(field);
    }
  }

  for (const field of requiredClaim) {
    const value = claim[field];

    if (
      value === undefined ||
      value === null ||
      (typeof value === "string" && !value.trim())
    ) {
      missing.push(`claim_data.${field}`);
    }
  }

  const warnings = [];

  if (data.event_type !== "claim.submitted") {
    warnings.push("Unexpected event type");
  }

  if (data.schema_version !== "1.0") {
    warnings.push("Unsupported schema version");
  }

  if (
    !Number.isInteger(data.claim_version) ||
    data.claim_version < 1
  ) {
    warnings.push("Invalid claim version");
  }

  if (
    claim.accident_date &&
    !/^\d{4}-\d{2}-\d{2}$/.test(claim.accident_date)
  ) {
    warnings.push("Invalid accident date format");
  }

  if (claim.accident_date && (/^\d{4}-\d{2}-\d{2}$/.test(claim.accident_date)) && (Number.isNaN(Date.parse(claim.accident_date)) || new Date(claim.accident_date).toISOString().slice(0,10) !== claim.accident_date)) warnings.push("Invalid accident calendar date");
  const complete = missing.length === 0;
  const valid = complete && warnings.length === 0;

  return {
    json: {
      ...data,
      validation: {
        valid,
        completeness: {
          complete,
          missing_fields: missing
        },
        warnings,
        requires_human_review: !valid,
        persistence_status: "NOT_PERSISTED",
        claim_status_changed: false
      }
    }
  };
});

