const data = $json;
const errors = [];

function requiredString(value, field) {
  if (typeof value !== 'string' || !value.trim()) {
    errors.push(`${field} is required`);
  }
}

requiredString(data.job_id, 'job_id');
requiredString(data.claim_id, 'claim_id');
requiredString(data.policy_number, 'policy_number');
requiredString(data.claim_type, 'claim_type');
requiredString(data.incident_description, 'incident_description');

if (!Number.isInteger(data.claim_version) || data.claim_version < 1) {
  errors.push('claim_version must be a positive integer');
}

const date = data.accident_date;

if (
  typeof date !== 'string' ||
  !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
  Number.isNaN(Date.parse(date)) ||
  new Date(date).toISOString().slice(0, 10) !== date
) {
  errors.push('accident_date must be a valid YYYY-MM-DD date');
}

if (
  !data.policy_verification ||
  typeof data.policy_verification !== 'object' ||
  Array.isArray(data.policy_verification)
) {
  errors.push('policy_verification is required');
} else {
  const p = data.policy_verification;

  if (typeof p.policy_found !== 'boolean') {
    errors.push('policy_found must be boolean');
  }

  if (typeof p.source_verified !== 'boolean') {
    errors.push('source_verified must be boolean');
  }

  for (const field of ['policy_status', 'coverage_status', 'evidence_status']) {
    requiredString(p[field], `policy_verification.${field}`);
  }

  if (!Array.isArray(p.review_reasons)) {
    errors.push('review_reasons must be an array');
  }
}

if (typeof data.incident_description === 'string' &&
    data.incident_description.length > 10000) {
  errors.push('incident_description exceeds maximum length');
}

return {
  json: {
    ...data,
    input_validation: {
      valid: errors.length === 0,
      errors,
      validated_at: new Date().toISOString()
    }
  }
};

const items = $input.all();

return items.map((item) => {
  const raw = item.json.text ?? item.json.output ?? "";
  const errors = [];
  let parsed = null;

  try {
    if (typeof raw === "object" && raw !== null) {
      parsed = raw;
    } else if (typeof raw === "string") {
      const cleaned = raw
        .trim()
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/, "")
        .trim();

      parsed = JSON.parse(cleaned);
    } else {
      errors.push("LLM response is not valid JSON");
    }
  } catch (error) {
    errors.push("JSON parsing failed: " + error.message);
  }

  if (
    !parsed ||
    typeof parsed !== "object" ||
    Array.isArray(parsed)
  ) {
    errors.push("Expected a JSON object");
  } else {
    if (typeof parsed.summary !== "string" ||
        !parsed.summary.trim()) {
      errors.push("Invalid summary");
    }

    if (!Array.isArray(parsed.observations)) {
      errors.push("Invalid observations");
    } else {
      for (const observation of parsed.observations) {
        if (
          !observation ||
          typeof observation.category !== "string" ||
          typeof observation.description !== "string" ||
          !["LOW", "MEDIUM", "HIGH"].includes(
            observation.severity
          )
        ) {
          errors.push("Invalid observation structure");
          break;
        }
      }
    }

    if (!Array.isArray(parsed.missing_information)) {
      errors.push("Invalid missing_information");
    }

    if (!Array.isArray(parsed.supervisor_questions)) {
      errors.push("Invalid supervisor_questions");
    }

    if (parsed.requires_human_review !== true) {
      errors.push("Human review must remain required");
    }

    if (
      Object.hasOwn(parsed, "final_claim_decision") &&
      parsed.final_claim_decision !== null
    ) {
      errors.push("LLM cannot make final claim decisions");
    }
  }

  return {
    json: {
      llm_validation: {
        valid: errors.length === 0,
        errors,
        validated_at: new Date().toISOString()
      },
      llm_analysis: errors.length === 0 ? parsed : null
    }
  };
});

const rules = $('Preliminary Analysis Engine').first().json;
const validation = $input.first().json;

const isValid =
  validation.llm_validation?.valid === true &&
  validation.llm_analysis !== null &&
  typeof validation.llm_analysis === "object";

const ai = isValid ? validation.llm_analysis : null;

const findings = Array.isArray(rules.findings)
  ? [...rules.findings]
  : [];

const missingInformation = Array.isArray(rules.missing_information)
  ? [...rules.missing_information]
  : [];

if (ai) {
  for (const observation of ai.observations ?? []) {
    findings.push({
      code: "AI_OBSERVATION",
      severity: observation.severity,
      message: observation.description,
      category: observation.category,
      source: "LLM",
      verification_status: "UNVERIFIED"
    });
  }

  for (const missing of ai.missing_information ?? []) {
    if (!missingInformation.includes(missing)) {
      missingInformation.push(missing);
    }
  }
} else {
  findings.push({
    code: "AI_OUTPUT_VALIDATION_FAILED",
    severity: "HIGH",
    message: "LLM output could not be validated.",
    source: "SYSTEM"
  });
}

const summary = ai
  ? ai.summary
  : rules.summary;

return [{
  json: {
    schema_version: "1.0",

    job_id: rules.job_id,
    claim_id: rules.claim_id,
    claim_version: rules.claim_version,

    analysis_type: "HYBRID_RULES_AND_LLM",
    analysis_status: isValid
      ? "COMPLETED"
      : "REQUIRES_REVIEW",

    summary,
    findings,
    missing_information: missingInformation,

    supervisor_questions: ai?.supervisor_questions ?? [],

    recommendation: "REFER_TO_HUMAN_REVIEW",
    requires_human_review: true,

    final_claim_decision: null,
    claim_status_changed: false,

    llm_validation: validation.llm_validation,

    analyzed_at: new Date().toISOString()
  }
}];

const rules=$input.first().json;
const intake=$('Normalize Webhook Input').first().json;
const flags=intake.document_flags ?? [];
return [{json:{text:JSON.stringify({summary:'Local preliminary checks completed. Document evidence and policy require supervisor verification.',observations:flags.map(f=>({category:'DOCUMENT_EVIDENCE',description:f,severity:'HIGH'})),missing_information:rules.missing_information,supervisor_questions:['Verify policy source and compare every flagged finding against its original document.'],requires_human_review:true,final_claim_decision:null})}}];

const intake=$('Normalize Webhook Input').first().json;
if(!intake.web_integration)return [];
let analysis=null;
try {analysis=$('Merge Analysis Results').first().json;} catch(e) {}
const issues=intake.document_flags ?? [];
const result=analysis ? {...analysis,analysis_type:'LOCAL_RULES_AND_DOCUMENT_EVIDENCE'} : {summary:'Claim validation requires correction and supervisor review.',findings:[],missing_information:[],requires_human_review:true,final_claim_decision:null};
const validation=$('Validate Claim Data').first().json.validation;
result.extracted=intake.claim_data;
result.evidence=intake.evidence;
result.flags=[...issues,...(validation?.completeness?.missing_fields ?? []),...(result.findings ?? []).map(f=>f.message)];
result.claim_version=intake.claim_version;
result.field_sources=intake.field_sources ?? {};
if (!analysis) { try {result.flags.push(...($('Prepare AI Input Review').first().json.review_reasons ?? []));} catch(e) {} }
return [{json:{case_id:intake.case_id,job_id:intake.job_id,result}}];
